namespace HollowNight.Logic
{
    public static partial class TalesText
    {
        static void Fill()
        {
            Add("open.1", "jida", "telling", "Amacahu!", "Amacahu!", "Amacahu !", "أماشاهو!");
            Add("open.2", "children", "", "Macahu!", "Macahu!", "Macahu !", "ماشاهو!");
            Add("open.3", "jida", "", "May God make it fine, and long as a thread.", "Rebbi ad tt-yesselhu, ad teɣzif am usaru.", "Que Dieu la rende belle, et longue comme un fil.", "ليجعلها الله جميلة، وطويلة كالخيط.");
            Add("open.4", "jida", "", "He was no bigger than your fist, and cleverer than all of us. They called him Mqidec.", "Ur yelli ara d ameqqran ugar n tdikelt-nwen, yugar-aɣ akk s leɛqel. Semman-as Mqidec.", "Il n'était pas plus gros que ton poing, et plus malin que nous tous. On l'appelait Mqidec.", "لم يكن أكبر من قبضة يدك، وكان أذكى منا جميعا. كانوا يسمونه مقيدش.");
            Add("open.5", "boy", "", "A rabbit? Rabbits are not clever.", "D awtul? Iwtal ur ɛqilen ara.", "Un lapin ? Les lapins ne sont pas malins.", "أرنب؟ الأرانب ليست ذكية.");
            Add("open.6", "jida", "teasing", "This one was. Listen.", "Wagi yeɛqel. Semḥess.", "Celui-là l'était. Écoute.", "هذا كان ذكيا. اسمع.");
            Add("close.1", "jida", "telling", "My tale went down the ravine, and I went down the road.", "Tamacahut-iw tedda s iɣzer, nekk ddiɣ s ubrid.", "Mon conte est parti par le ravin, et moi par le chemin.", "حكايتي مضت في الوادي، وأنا مضيت في الطريق.");
            Add("close.2", "jida", "", "And that is why we keep the lamp lit.", "Ɣef aya i nettaǧǧa taftilt tecɛel.", "Et c'est pour cela que nous laissons la lampe allumée.", "ولهذا نبقي المصباح مضاءً.");
            Add("close.3", "girl", "", "Jida, is she still out there?", "A Jida, mazal-itt dinna?", "Jida, elle est encore là-dehors ?", "جدّة، هل ما زالت هناك في الخارج؟");
            Add("close.4", "jida", "teasing", "Go to sleep.", "Ṭṭes.", "Dors.", "نامي.");
            Add("t1.intro.1", "jida", "telling", "On Yennayer eve, the ogress Teryel came down from her house above the village and stole the jar of lamp oil from this very house.", "Deg yiḍ n Yennayer, Teryel tṣubb-d seg uxxam-is nnig taddart, tuker taxabit n zzit n teftilt seg uxxam-agi.", "La veille de Yennayer, l'ogresse Teryel descendit de sa maison au-dessus du village et vola la jarre d'huile de la lampe de cette maison même.", "عشية يناير، نزلت الغولة تريال من بيتها فوق القرية وسرقت جرّة زيت المصباح من هذا البيت بالذات.");
            Add("t1.intro.2", "girl", "", "Our house?", "Axxam-nneɣ?", "Notre maison ?", "بيتنا؟");
            Add("t1.intro.3", "jida", "hushed", "This one. No oil, no lamp. No lamp at midnight, and the dead find no road home.", "Wagi. Ulac zzit, ulac taftilt. Ulac taftilt di ttnaṣfa n yiḍ, lmeyytin ur ttafen ara abrid.", "Celle-ci. Pas d'huile, pas de lampe. Pas de lampe à minuit, et les morts ne trouvent pas le chemin du retour.", "هذا. لا زيت، لا مصباح. لا مصباح عند منتصف الليل، فلا يجد الموتى طريق العودة.");
            Add("t1.intro.4", "jida", "telling", "So Mqidec went up the hill, into her kitchen, while she slept by her fire.", "Mqidec yuli s adrar, yekcem s axxam-is n tettemt, nettat teṭṭes ɣer tmes.", "Alors Mqidec monta la colline, entra dans sa cuisine, pendant qu'elle dormait près de son feu.", "فصعد مقيدش التلّ، ودخل مطبخها، بينما كانت نائمة قرب نارها.");
            Add("t1.intro.5", "boy", "", "Into an ogress's kitchen? Alone?", "S axxam n tettemt n Teryel? Weḥd-es?", "Dans la cuisine d'une ogresse ? Tout seul ?", "إلى مطبخ غولة؟ وحده؟");
            Add("t1.intro.6", "jida", "teasing", "He was not alone. Her pots were awake.", "Ur yelli ara weḥd-es. Tisilin-is ukint.", "Il n'était pas seul. Ses marmites étaient réveillées.", "لم يكن وحده. قدورها كانت مستيقظة.");
            Add("t1.s1", "jida", "", "The jars along the wall had eyes. Hit one fast and it is shards. Touch one slowly and it bites.", "Ikufan ɣer lḥiḍ sɛan allen. Wwet-it s zzerb ad yerreẓ. Nnal-it s leɛqel ad k-yeqqes.", "Les jarres le long du mur avaient des yeux. Frappe-en une vite, et ce sont des tessons. Touche-la lentement, et elle mord.", "الجرار على الحائط كانت لها عيون. اضرب واحدة بسرعة تتكسّر شظايا. المسها ببطء تعضّك.");
            Add("t1.s1.child", "girl", "", "Did it bite him?", "Teqqes-it?", "Elle l'a mordu ?", "هل عضّته؟");
            Add("t1.s2", "jida", "", "A pot on a shelf is a stone waiting to roll. Push it, and let it do the work.", "Tasilt ɣef tferka d aẓru yettraǧun ad yebrenbez. Ḍegger-itt, eǧǧ-itt ad texdem.", "Une marmite sur une étagère est une pierre qui attend de rouler. Pousse-la, et laisse-la travailler.", "قدر على الرفّ حجر ينتظر أن يتدحرج. ادفعها، ودعها تعمل.");
            Add("t1.s2.child", "boy", "", "I would have thrown it at her.", "Nekk ad as-tt-ḍeggreɣ.", "Moi, je la lui aurais jetée dessus.", "أنا كنت سأرميها عليها.");
            Add("t1.s3", "jida", "", "The hearth pots were still hot. Drop into one, and it throws you to the loft.", "Tisilin n lkanun mazal ḥmant. Ɣli deg yiwet, ad k-tḍegger s taɛrict.", "Les marmites du foyer étaient encore chaudes. Tombe dans l'une, et elle te lance au grenier.", "قدور الموقد كانت ما زالت ساخنة. اسقط في واحدة، فترميك إلى العلّية.");
            Add("t1.s3.child", "girl", "", "Did he burn?", "Yerɣa?", "Il s'est brûlé ?", "هل احترق؟");
            Add("t1.s4", "jida", "hushed", "And there she slept, with the oil jar under her head. He could not lift it. So he looked at the room.", "Dinna teṭṭes, taxabit n zzit ddaw uqerru-s. Ur yezmir ara ad tt-yerfed. Imir imuqel axxam.", "Et là elle dormait, la jarre d'huile sous la tête. Il ne pouvait pas la soulever. Alors il regarda la pièce.", "وهناك كانت نائمة، وجرّة الزيت تحت رأسها. لم يستطع أن يرفعها. فنظر إلى الغرفة.");
            Add("t1.s4.child", "boy", "", "The big jar!", "Akufi ameqqran!", "La grande jarre !", "الجرّة الكبيرة!");
            Add("t1.end.1", "jida", "telling", "He rolled the great grain jar off the loft. It came down over her head like a hat.", "Yebrenbez-d akufi ameqqran seg taɛrict. Yeɣli-d ɣef uqerru-s am tcacit.", "Il fit rouler la grande jarre à grain depuis le grenier. Elle tomba sur sa tête comme un chapeau.", "دحرج جرّة الحبوب الكبيرة من العلّية. فنزلت على رأسها كالقبّعة.");
            Add("t1.end.2", "teryel", "", "Who is in my kitchen?!", "Anwa yellan deg uxxam-iw n tettemt?!", "Qui est dans ma cuisine ?!", "من في مطبخي؟!");
            Add("t1.end.3", "jida", "teasing", "She shouted into the jar for the rest of the night. He took the oil and went home under the door.", "Tesɣuyy deg ukufi armi d tafrara. Yeddem zzit, yuɣal s axxam ddaw tewwurt.", "Elle cria dans la jarre tout le reste de la nuit. Il prit l'huile et rentra par-dessous la porte.", "ظلّت تصرخ في الجرّة بقية الليل. أخذ الزيت وعاد إلى البيت من تحت الباب.");
            Add("t1.end.4", "girl", "", "And the lamp?", "Taftilt?", "Et la lampe ?", "والمصباح؟");
            Add("t1.end.5", "jida", "hushed", "Ah. The lamp. That is tomorrow's tale.", "Ah. Taftilt. Tagi d tamacahut n uzekka.", "Ah. La lampe. Ça, c'est le conte de demain.", "آه. المصباح. تلك حكاية الغد.");
            Add("t2.intro.1", "jida", "telling", "The oil was home. But the lamp was gone. Teryel had taken it, and she had woven it into her loom to keep its light for herself.", "Zzit tuɣal s axxam. Maca taftilt ulac-itt. Tedddem-itt Teryel, teẓḍa-tt deg uzeṭṭa-s akken ad teṭṭef tafat-is i yiman-is.", "L'huile était rentrée. Mais la lampe avait disparu. Teryel l'avait prise, et l'avait tissée dans son métier pour garder sa lumière pour elle.", "عاد الزيت إلى البيت. لكن المصباح اختفى. أخذته تريال، ونسجته في منسجها لتحتفظ بنوره لنفسها.");
            Add("t2.intro.2", "boy", "", "A lamp in a loom?", "Taftilt deg uzeṭṭa?", "Une lampe dans un métier à tisser ?", "مصباح في منسج؟");
            Add("t2.intro.3", "jida", "hushed", "A loom has a soul, they say. Hers had a temper. The threads ran from wall to wall, and every one of them was waiting for him.", "Azeṭṭa yesɛa ṛṛuḥ, qqaren. Win-is yesɛa urrif. Isaruyen seg lḥiḍ ɣer lḥiḍ, yal yiwen yettraǧu-t.", "Un métier a une âme, dit-on. Le sien avait du caractère. Les fils allaient d'un mur à l'autre, et chacun l'attendait.", "للمنسج روح، كما يقولون. ومنسجها كان حادّ الطبع. الخيوط ممدودة من حائط إلى حائط، وكلّ خيط ينتظره.");
            Add("t2.intro.4", "jida", "telling", "He went back up the hill.", "Yuɣal yuli s adrar.", "Il remonta la colline.", "عاد وصعد التلّ.");
            Add("t2.s1", "jida", "", "Sticky silk. It holds you once, like a hand that does not want to let go. Then it tears.", "Lḥarir yettaṭṭafen. Yettaṭṭaf-ik yiwet n tikkelt, am ufus ur nebɣi ara ad iserreḥ. Imir yettqerric.", "De la soie collante. Elle te retient une fois, comme une main qui ne veut pas lâcher. Puis elle se déchire.", "حرير لاصق. يمسكك مرّة واحدة، كيد لا تريد أن تترك. ثم يتمزّق.");
            Add("t2.s1.child", "girl", "", "Her spiders were on it?", "Tissist-is fell-as?", "Ses araignées étaient dessus ?", "وعناكبها عليه؟");
            Add("t2.s2", "jida", "", "Not every thread is sticky. The tight ones she strung to throw things away from her. Let them throw you.", "Mačči yal asaru yettaṭṭaf. Wid yeǧǧhden tcedd-iten akken ad ḍeggren. Eǧǧ-iten ad k-ḍeggren.", "Tous les fils ne collent pas. Les tendus, elle les a montés pour rejeter les choses loin d'elle. Laisse-les te lancer.", "ليست كل الخيوط لاصقة. المشدودة منها نصبتها لترمي الأشياء بعيدا عنها. دعها ترميك.");
            Add("t2.s2.child", "boy", "", "Like a sling!", "Am umegred!", "Comme une fronde !", "كالمقلاع!");
            Add("t2.s3", "jida", "", "Her long threads cross the whole room. Catch one and slide. Whatever sits on it will meet you at speed.", "Isaruyen-is iɣezfanen zegren axxam akk. Ṭṭef yiwen, ɣli. Ayen yeqqimen fell-as ad k-imlil s zzerb.", "Ses longs fils traversent toute la pièce. Attrape-en un et glisse. Ce qui s'y trouve viendra te rencontrer à toute vitesse.", "خيوطها الطويلة تعبر الغرفة كلّها. أمسك واحدا وانزلق. وكلّ ما يجلس عليه سيلقاك بسرعة.");
            Add("t2.s3.child", "girl", "", "Did he fall?", "Yeɣli?", "Il est tombé ?", "هل سقط؟");
            Add("t2.s4", "jida", "hushed", "She was waiting at the loom with the lamp in it. He could not reach it with her there. So he ran, and he made her run.", "Tettraǧu ɣer uzeṭṭa, taftilt deg-s. Ur yezmir ara ad tt-yaweḍ nettat dinna. Imir yuzzel, yesuzzel-itt.", "Elle l'attendait au métier, la lampe dedans. Il ne pouvait pas l'atteindre avec elle là. Alors il courut, et il la fit courir.", "كانت تنتظر عند المنسج، والمصباح فيه. لم يستطع الوصول إليه وهي هناك. فركض، وجعلها تركض.");
            Add("t2.s4.child", "boy", "", "Into the threads!", "Deg isaruyen!", "Dans les fils !", "في الخيوط!");
            Add("t2.end.1", "jida", "telling", "She chased him through her own weaving until she was wound up like a shuttle. Imagine it.", "Tezzuɣer-it deg uẓeṭṭa-s armi tettwazḍa am tḥebbuzt. Xemmem-as.", "Elle le poursuivit à travers son propre tissage jusqu'à être enroulée comme une navette. Imaginez.", "طاردته عبر نسيجها حتى التفّت كالمكّوك. تصوّروا.");
            Add("t2.end.2", "teryel", "", "My loom! My own loom!", "Azeṭṭa-w! Azeṭṭa-w nekk!", "Mon métier ! Mon propre métier !", "منسجي! منسجي أنا!");
            Add("t2.end.3", "jida", "teasing", "He took the lamp from the threads and went out through the roof tiles.", "Yekkes taftilt seg isaruyen, yeffeɣ seg iqermuden.", "Il prit la lampe dans les fils et sortit par les tuiles du toit.", "أخذ المصباح من الخيوط وخرج من قرميد السقف.");
            Add("t2.end.4", "girl", "", "Now he can light it!", "Tura yezmer ad tt-yesceɛl!", "Maintenant il peut l'allumer !", "الآن يستطيع أن يشعله!");
            Add("t2.end.5", "jida", "hushed", "He lit it on the roof. And every ijenni in the gorge saw it.", "Yesceɛl-itt ɣef ssqef. Yal aǧenniw n yiɣzer yeẓra-tt.", "Il l'alluma sur le toit. Et tous les djinns de la gorge le virent.", "أشعله على السطح. فرآه كلّ جنّيّ في الوادي.");
            Add("t3.intro.1", "jida", "telling", "The way home runs down through the Iron Gates, and he carried the lit lamp. Teryel came after him, and the gorge has its own people.", "Abrid s axxam yettṣubbu di Tiwura n wuzzal, netta yerfed taftilt tecɛel. Teryel tedda deffir-s, iɣzer yesɛa imdanen-is.", "Le chemin du retour descend par les Portes de Fer, et il portait la lampe allumée. Teryel le suivait, et la gorge a ses propres gens.", "طريق العودة ينزل عبر أبواب الحديد، وكان يحمل المصباح مشتعلا. تبعته تريال، وللوادي أهله.");
            Add("t3.intro.2", "girl", "", "What people?", "Anwi imdanen?", "Quels gens ?", "أيّ أهل؟");
            Add("t3.intro.3", "jida", "hushed", "The ijenniwen. The ones that live in the springs and the old trees. Do not whistle there at night.", "Ijenniwen. Wid yettidiren deg tliwa d ttjur tiqdimin. Ur ssefṛiḍ ara dinna deg yiḍ.", "Les ijenniwen. Ceux qui vivent dans les sources et les vieux arbres. Ne siffle pas là-bas la nuit.", "الجنّ. الذين يسكنون في العيون والأشجار القديمة. لا تصفّر هناك ليلا.");
            Add("t3.intro.4", "boy", "", "I am not afraid of them.", "Ur ttaggadeɣ ara seg-sen.", "Je n'ai pas peur d'eux.", "لا أخاف منهم.");
            Add("t3.intro.5", "jida", "teasing", "Then hold the lamp.", "Ihi ṭṭef taftilt.", "Alors tiens la lampe.", "إذن أمسك المصباح.");
            Add("t3.s1", "jida", "", "The wind comes up through the narrows. It lifts whoever is light enough. He was lighter than the wind, and the wind knew it.", "Aḍu yettali-d seg tezzelmaḍ. Yettrefid win yifsusen. Netta yifsus ɣef waḍu, aḍu yeẓra-t.", "Le vent monte par les défilés. Il soulève qui est assez léger. Il était plus léger que le vent, et le vent le savait.", "تصعد الريح عبر المضائق. ترفع من كان خفيفا بما يكفي. كان أخفّ من الريح، والريح تعرف ذلك.");
            Add("t3.s1.child", "girl", "", "And the lamp did not go out?", "Taftilt ur texsi ara?", "Et la lampe ne s'est pas éteinte ?", "والمصباح لم ينطفئ؟");
            Add("t3.s2", "jida", "", "The old stones of the road lie balanced on their posts. Land hard on one end and watch the other.", "Iẓra iqdimen n ubrid ttwaktalen ɣef tgejda-nsen. Ɣli s ǧǧehd ɣef yiwet n tama, muqel tayeḍ.", "Les vieilles pierres de la route reposent en équilibre sur leurs piliers. Atterris fort sur un bout et regarde l'autre.", "حجارة الطريق القديمة متوازنة على أعمدتها. اهبط بقوّة على طرف وانظر إلى الطرف الآخر.");
            Add("t3.s2.child", "boy", "", "Like a seesaw!", "Am tḥewwaṣt!", "Comme une balançoire !", "كالأرجوحة!");
            Add("t3.s3", "jida", "", "In the ravine the stones hang by frayed roots, and some crumble when you stand on them. Watch the one that trembles.", "Deg yiɣzer iẓra ttɛellaqen s izuran yeqqersen, kra ttruẓun mi tbeddeḍ fell-asen. Muqel win yettergigin.", "Dans le ravin, les pierres pendent à des racines usées, et certaines s'effritent quand on se tient dessus. Regarde celle qui tremble.", "في الوادي تتدلّى الحجارة من جذور متآكلة، وبعضها يتفتّت حين تقف عليه. راقب التي ترتجف.");
            Add("t3.s3.child", "girl", "", "Jida, did he get out?", "A Jida, yeffeɣ?", "Jida, il s'en est sorti ?", "جدّة، هل خرج؟");
            Add("t3.s3.child2", "jida", "", "Wait.", "Rǧu.", "Attends.", "انتظري.");
            Add("t3.s4", "jida", "hushed", "The old gate stone of the pass still hangs on its post. She was close behind him. He had one leap left.", "Aẓru aqdim n tewwurt n tizi mazal yettɛellaq ɣef tgejdit-is. Nettat teqreb deffir-s. Yeqqim-as yiwen n uneggez.", "La vieille pierre de la porte du col pend encore à son pilier. Elle était juste derrière lui. Il lui restait un saut.", "حجر باب المضيق القديم ما زال معلّقا على عموده. كانت قريبة خلفه. بقيت له قفزة واحدة.");
            Add("t3.s4.child", "boy", "", "Jump!", "Neggez!", "Saute !", "اقفز!");
            Add("t3.end.1", "jida", "telling", "He came down hard on the balanced stone, and the gate dropped behind him with Teryel on the far side.", "Yeɣli-d s ǧǧehd ɣef uẓru yettwaktalen, tawwurt teɣli deffir-s, Teryel ɣer tama nniḍen.", "Il retomba lourdement sur la pierre en équilibre, et la porte tomba derrière lui, Teryel de l'autre côté.", "هبط بقوّة على الحجر المتوازن، فسقط الباب خلفه وتريال في الجهة الأخرى.");
            Add("t3.end.2", "teryel", "", "Open it! Open it, you fly!", "Ldi-tt! Ldi-tt, a yizi!", "Ouvre ! Ouvre, espèce de mouche !", "افتحه! افتحه يا ذبابة!");
            Add("t3.end.3", "jida", "teasing", "She is still shouting, they say, when the wind comes from the south.", "Mazal tesɣuyyu, qqaren, mi d-yusa waḍu seg unẓul.", "Elle crie encore, dit-on, quand le vent vient du sud.", "ما زالت تصرخ، كما يقولون، حين تهبّ الريح من الجنوب.");
            Add("t3.end.4", "jida", "telling", "He walked up the hill with the lamp. The door of this house was open, and the lamp went on the sill, and it is there now.", "Yuli s adrar s teftilt. Tawwurt n uxxam-agi teldi, taftilt ters ɣef uɣerbaz, atan dinna tura.", "Il monta la colline avec la lampe. La porte de cette maison était ouverte, la lampe fut posée sur le rebord, et elle y est encore.", "صعد التلّ بالمصباح. كان باب هذا البيت مفتوحا، فوُضع المصباح على العتبة، وهو هناك الآن.");
            Add("t3.end.5", "girl", "", "That one?", "Tagi?", "Celle-là ?", "هذا؟");
            Add("t3.end.6", "jida", "hushed", "That one. Aseggas ameggaz.", "Tagi. Aseggas ameggaz.", "Celle-là. Aseggas ameggaz.", "هذا. أسقاس أمقاز.");
            Add("r.firstSmash", "jida", "", "Good. That one was loud.", "Igerrez. Wagi yesla-yas umḍiq.", "Bien. Celle-là a fait du bruit.", "حسنا. تلك كانت صاخبة.");
            Add("r.smashAll", "boy", "", "Three! All three!", "Tlata! Akk tlata!", "Trois ! Toutes les trois !", "ثلاث! كلّها الثلاث!");
            Add("r.death", "girl", "", "Jida, no!", "A Jida, uhu!", "Jida, non !", "جدّة، لا!");
            Add("r.deathAgain", "jida", "", "Slowly is how rabbits get eaten. Again.", "S leɛqel i ttmaččan iwtal. Tikkelt nniḍen.", "C'est lentement que les lapins se font manger. Encore.", "على مهل تُؤكل الأرانب. مرّة أخرى.");
            Add("r.deathThird", "jida", "", "Stop. Breathe. Where are they, and where are you?", "Ḥbes. Snuffes. Anda llan, anda telliḍ?", "Arrête. Respire. Où sont-elles, et où es-tu ?", "توقّف. تنفّس. أين هي، وأين أنت؟");
            Add("r.crush", "boy", "", "He crushed it!", "Yerẓa-t!", "Il l'a écrasée !", "سحقها!");
            Add("r.web", "girl", "", "It is holding him!", "Teṭṭef-it!", "Elle le retient !", "إنها تمسكه!");
            Add("r.boing", "boy", "", "Again! Again!", "Tikkelt nniḍen!", "Encore ! Encore !", "مرّة أخرى! مرّة أخرى!");
            Add("r.zip", "jida", "", "Hold on.", "Ṭṭef.", "Tiens bon.", "تمسّك.");
            Add("r.trap", "jida", "teasing", "Now.", "Tura.", "Maintenant.", "الآن.");
            Add("tip.launch", "", "", "Pull him back like a sling. Let go to leap.", "Jbed-it ɣer deffir am umegred. Serreḥ-as ad ineggez.", "Tire-le en arrière comme une fronde. Lâche pour sauter.", "اسحبه إلى الخلف كالمقلاع. اتركه ليقفز.");
            Add("tip.hunter", "", "", "It smelled you. Hit it fast, or it bites.", "Yesraḥ-ik. Wwet-it s zzerb, neɣ ad k-yeqqes.", "Elle t'a senti. Frappe vite, ou elle mord.", "شمّك. اضربه بسرعة، وإلا عضّك.");
            Add("tip.dash", "", "", "Tap in the air to dash. Once per leap.", "Sṭebṭeb deg ugama ad yazzel. Yiwet n tikkelt i yal aneggez.", "Tape en l'air pour foncer. Une fois par saut.", "انقر في الهواء ليندفع. مرّة في كلّ قفزة.");
            Add("tip.roll", "", "", "A loose pot rolls when you hit it. Into the others, or off the edge.", "Tasilt tettbrenbiz mi tt-tewteḍ. Ɣer tiyaḍ, neɣ seg rrif.", "Une marmite libre roule quand tu la frappes. Dans les autres, ou par-dessus bord.", "القدر الطليقة تتدحرج حين تضربها. إلى الأخرى، أو عن الحافة.");
            Add("tip.cannon", "", "", "A hearth pot throws you. Drop in.", "Tasilt n lkanun ad k-tḍegger. Ɣli deg-s.", "Une marmite du foyer te lance. Tombe dedans.", "قدر الموقد ترميك. اسقط فيها.");
            Add("tip.web", "", "", "Sticky silk. It holds you once. Leap again from it.", "Lḥarir yettaṭṭafen. Yettaṭṭaf-ik yiwet n tikkelt. Neggez seg-s.", "Soie collante. Elle te retient une fois. Saute à nouveau depuis elle.", "حرير لاصق. يمسكك مرّة. اقفز منه ثانية.");
            Add("tip.trampoline", "", "", "Tight silk. It throws you back, hard.", "Lḥarir yeǧǧhden. Ad k-iḍegger ɣer deffir, s ǧǧehd.", "Soie tendue. Elle te renvoie, fort.", "حرير مشدود. يرميك إلى الخلف بقوّة.");
            Add("tip.zip", "", "", "A long thread. Touch it to slide. Tap to let go.", "Asaru aɣezfan. Nnal-it ad teɣliḍ. Sṭebṭeb ad tserrḥeḍ.", "Un long fil. Touche-le pour glisser. Tape pour lâcher.", "خيط طويل. المسه لتنزلق. انقر لتترك.");
            Add("tip.mover", "", "", "It swings on her thread. Ride it, and leap when it leans close.", "Yettḥuzzu ɣef usaru-s. Rkeb-it, neggez mi d-iqerreb.", "Il se balance sur son fil. Monte dessus, et saute quand il se rapproche.", "يتأرجح على خيطها. اركبه، واقفز حين يقترب.");
            Add("tip.wind", "", "", "The wind in the narrows lifts you. Leap into it.", "Aḍu n tezzelmaḍ ad k-irfed. Neggez deg-s.", "Le vent des défilés te soulève. Saute dedans.", "ريح المضيق ترفعك. اقفز فيها.");
            Add("tip.seesaw", "", "", "Balanced on a post. Land hard on one end and the other end throws.", "Yettwaktal ɣef tgejdit. Ɣli s ǧǧehd ɣef yiwet n tama, tayeḍ ad tḍegger.", "En équilibre sur un pilier. Atterris fort sur un bout, et l'autre bout lance.", "متوازن على عمود. اهبط بقوّة على طرف فيرمي الطرف الآخر.");
            Add("tip.drop", "", "", "A frayed root. Stand on the stone and it falls. Leap, or ride it.", "Aẓar yeqqersen. Bedd ɣef uẓru ad yeɣli. Neggez, neɣ rkeb-it.", "Une racine usée. Tiens-toi sur la pierre et elle tombe. Saute, ou reste dessus.", "جذر متآكل. قف على الحجر فيسقط. اقفز، أو اركبه.");
            Add("tip.ghost", "", "", "It crumbles and comes back. It trembles before it goes.", "Yettruẓu yettuɣal-d. Yettergigi uqbel ad iruḥ.", "Elle s'effrite et revient. Elle tremble avant de partir.", "يتفتّت ويعود. يرتجف قبل أن يذهب.");
            Add("tip.ijenni", "", "", "A night spirit. Dash through it, or go around.", "Aǧenniw n yiḍ. Azzel deg-s, neɣ zzi-yas.", "Un esprit de la nuit. Fonce à travers, ou contourne-le.", "جنّيّ الليل. اندفع عبره، أو دُر حوله.");
            Add("tip.trap", "", "", "Teryel is here. No fighting. Look at the room.", "Teryel atta-ya. Ulac imenɣi. Muqel axxam.", "Teryel est là. Pas de combat. Regarde la pièce.", "تريال هنا. لا قتال. انظر إلى الغرفة.");
            Add("ui.title", "", "", "The Tales of Mqidec", "Timucuha n Mqidec", "Les contes de Mqidec", "حكايات مقيدش");
            Add("ui.tagline", "", "", "Teryel wants to eat him. He has other plans.", "Teryel tebɣa ad t-tečč. Netta yesɛa ayen nniḍen deg uqerru-s.", "Teryel veut le manger. Il a d'autres projets.", "تريال تريد أن تأكله. وله خطط أخرى.");
            Add("ui.play", "", "", "Play", "Urar", "Jouer", "العب");
            Add("ui.tales", "", "", "The tales", "Timucuha", "Les contes", "الحكايات");
            Add("ui.language", "", "", "Language", "Tutlayt", "Langue", "اللغة");
            Add("ui.back", "", "", "Back", "Uɣal", "Retour", "رجوع");
            Add("ui.skip", "", "", "Skip", "Ɛeddi", "Passer", "تخطّ");
            Add("ui.tap", "", "", "Tap to continue", "Sit akken ad tkemmleḍ", "Touche pour continuer", "انقر للمتابعة");
            Add("ui.gotit", "", "", "Got it", "Fehmeɣ", "Compris", "فهمت");
            Add("ui.paused", "", "", "Paused", "Yeḥbes", "En pause", "متوقّف");
            Add("ui.resume", "", "", "Resume", "Kemmel", "Reprendre", "استأنف");
            Add("ui.next", "", "", "Next", "Ɣer zdat", "Suivant", "التالي");
            Add("ui.restart", "", "", "Restart stage", "Ales-d", "Recommencer", "أعد المرحلة");
            Add("ui.map", "", "", "The tales", "Timucuha", "Les contes", "الحكايات");
            Add("ui.soundOn", "", "", "Sound on", "Imesli yeddem", "Son activé", "الصوت مفعّل");
            Add("ui.soundOff", "", "", "Sound off", "Imesli yensa", "Son coupé", "الصوت مغلق");
            Add("ui.night", "", "", "Night", "Iḍ", "Nuit", "الليلة");
            Add("ui.stage", "", "", "Stage", "Aswir", "Étape", "المرحلة");
            Add("ui.doorOpens", "", "", "He is through the door", "Yeffeɣ seg tewwurt", "Il a passé la porte", "عبر الباب");
            Add("ui.trapped", "", "", "Teryel is trapped!", "Teryel teṭṭef!", "Teryel est piégée !", "وقعت تريال في الفخّ!");
            Add("ui.allThree", "", "", "Three broken. Not one follows him home.", "Tlata rrẓen. Ula d yiwen ur t-iḍeffer s axxam.", "Trois brisés. Aucun ne le suit jusqu'à la maison.", "ثلاثة تحطّمت. لا أحد يتبعه إلى البيت.");
            Add("ui.someBroken", "", "", "{n} of 3 broken. The rest are still hunting.", "{n} seg 3 rrẓen. Wiyaḍ mazal ttnadin.", "{n} sur 3 brisés. Les autres chassent encore.", "{n} من 3 تحطّمت. البقية ما زالت تطارد.");
            Add("ui.noneBroken", "", "", "He got away, but all three are still hunting.", "Yerwel, maca tlata mazal ttnadin.", "Il s'est échappé, mais les trois chassent encore.", "نجا، لكن الثلاثة ما زالت تطارد.");
            Add("tale.1", "", "", "Teryel's kitchen", "Taxxamt n Teryel", "La cuisine de Teryel", "مطبخ تريال");
            Add("tale.2", "", "", "The loom room", "Taxxamt n uzeṭṭa", "La chambre du métier", "غرفة المنسج");
            Add("tale.3", "", "", "The Iron Gates", "Tiwura n wuzzal", "Les Portes de Fer", "أبواب الحديد");
            Add("stage.1", "", "", "The jar wall", "Ikufan", "Le mur des jarres", "جدار الجرار");
            Add("stage.2", "", "", "The rolling pot", "Tasilt", "La marmite qui roule", "القدر المتدحرجة");
            Add("stage.3", "", "", "The hearth throws", "Lkanun", "Le foyer qui lance", "الموقد يرمي");
            Add("stage.4", "", "", "Teryel asleep", "Teryel teṭṭes", "Teryel endormie", "تريال نائمة");
            Add("stage.5", "", "", "Sticky silk", "Lḥarir", "La soie collante", "الحرير اللاصق");
            Add("stage.6", "", "", "Tight silk", "Tasfift", "La soie tendue", "الحرير المشدود");
            Add("stage.7", "", "", "The long thread", "Asaru aɣezfan", "Le long fil", "الخيط الطويل");
            Add("stage.8", "", "", "Teryel in the loom", "Teryel deg uzeṭṭa", "Teryel dans le métier", "تريال في المنسج");
            Add("stage.9", "", "", "The wind", "Aḍu", "Le vent", "الريح");
            Add("stage.10", "", "", "The balanced stone", "Aẓru yettwaktalen", "La pierre en équilibre", "الحجر المتوازن");
            Add("stage.11", "", "", "The ravine", "Iɣzer", "Le ravin", "الوادي");
            Add("stage.12", "", "", "The gate", "Tawwurt", "La porte", "الباب");
            Add("who.jida", "", "", "Jida", "Jida", "Jida", "الجدّة");
            Add("who.girl", "", "", "The girl", "Taqcict", "La fille", "البنت");
            Add("who.boy", "", "", "The boy", "Aqcic", "Le garçon", "الولد");
            Add("who.children", "", "", "The children", "Igerdan", "Les enfants", "الأطفال");
            Add("who.teryel", "", "", "Teryel", "Teryel", "Teryel", "تريال");
            Add("hero.name", "", "", "Mqidec", "Mqidec", "Mqidec", "مقيدش");
            Add("t4.intro.1", "jida", "telling", "On the morning of Yennayer the women baked the bread of the new year in the village oven. By evening the bread was gone, and so was Teryel.", "Ṣbeḥ n Yennayer, tilawin ssewwent aɣrum n useggas amaynut deg ufurnu n taddart. Tameddit, aɣrum ulac-it, Teryel daɣen ulac-itt.", "Le matin de Yennayer, les femmes ont cuit le pain de la nouvelle année au four du village. Le soir, le pain avait disparu, et Teryel aussi.", "صباح يناير، خبزت النساء خبز العام الجديد في فرن القرية. وفي المساء اختفى الخبز، واختفت تريال أيضا.");
            Add("t4.intro.2", "boy", "", "Teryel eats bread?", "Teryel tettett aɣrum?", "Teryel mange du pain ?", "تريال تأكل الخبز؟");
            Add("t4.intro.3", "jida", "teasing", "She eats everything. But this bread she hid on the highest roof of the citadel, where her ravens keep watch.", "Tettett kullec. Maca aɣrum-agi teffer-it ɣef ssqef ufellay n Lqelɛa, anda ttɛassan ijeɣdan-is.", "Elle mange de tout. Mais ce pain, elle l'a caché sur le plus haut toit de la citadelle, là où ses corbeaux montent la garde.", "تأكل كل شيء. لكن هذا الخبز خبّأته على أعلى سطح في القلعة، حيث تحرسه غربانها.");
            Add("t4.intro.4", "jida", "hushed", "So Mqidec went up over the roofs, where the tiles are old and loose, and the street is very far below.", "Mqidec yuli ɣef ssqef, anda iqermuden qqduren, ttḥerriken, abrid ddaw-s yebɛed aṭas.", "Alors Mqidec monta sur les toits, là où les tuiles sont vieilles et branlantes, et la rue très loin en dessous.", "فصعد مقيدش فوق السطوح، حيث القرميد قديم ومتخلخل، والشارع بعيد جدا في الأسفل.");
            Add("t4.intro.5", "girl", "", "I don't like ravens.", "Ur ḥemmleɣ ara ijeɣdan.", "Je n'aime pas les corbeaux.", "لا أحب الغربان.");
            Add("t4.s1", "jida", "", "Old tiles slide. Land on a roof and you go down it, faster and faster, and off the edge.", "Iqermuden iqdimen ttḥuddun. Ɣli ɣef ssqef ad tḥuddeḍ fell-as, s zzerb, armi d rrif.", "Les vieilles tuiles glissent. Pose-toi sur un toit et tu le descends, de plus en plus vite, jusqu'au bord.", "القرميد القديم ينزلق. اهبط على سطح فتنزلق عليه، أسرع فأسرع، حتى الحافة.");
            Add("t4.s1.child", "boy", "", "Like the snow on the hill!", "Am udfel deg wedrar!", "Comme la neige sur la colline !", "مثل الثلج على التلّ!");
            Add("t4.s2", "jida", "", "The ravens sleep under the stacks of loose tiles. Hit a stack hard and it goes over the edge.", "Ijeɣdan ṭṭsen ddaw ikedduse n iqermuden. Wwet akeddus s ǧǧehd ad yeɣli seg rrif.", "Les corbeaux dorment sous les piles de tuiles branlantes. Frappe une pile fort, et elle bascule par-dessus le bord.", "تنام الغربان تحت أكوام القرميد المتخلخل. اضرب كومة بقوّة فتسقط من الحافة.");
            Add("t4.s2.child", "girl", "", "On the ravens?", "Ɣef ijeɣdan?", "Sur les corbeaux ?", "على الغربان؟");
            Add("t4.s3", "jida", "", "Slide down a roof fast enough, and you hit the stack at the bottom without even trying.", "Ḥudd ɣef ssqef s zzerb, ad tewteḍ akeddus ddaw-s war ma tɛerḍeḍ.", "Glisse assez vite le long d'un toit, et tu frappes la pile en bas sans même essayer.", "انزلق على السطح بسرعة كافية، فتضرب الكومة في الأسفل دون أن تحاول.");
            Add("t4.s3.child", "boy", "", "Faster!", "S zzerb!", "Plus vite !", "أسرع!");
            Add("t4.s4", "jida", "hushed", "And there she was, on the flat roof, sitting by the chimney with the bread in her lap.", "Atan dinna, ɣef ssqef yettwaɛdlen, teqqim ɣer ddexxan, aɣrum ɣef tgecrar-is.", "Et elle était là, sur le toit plat, assise près de la cheminée, le pain sur les genoux.", "وكانت هناك، على السطح المستوي، جالسة قرب المدخنة والخبز في حجرها.");
            Add("t4.s4.child", "girl", "", "The stack! Above her!", "Akeddus! Nnig-s!", "La pile ! Au-dessus d'elle !", "الكومة! فوقها!");
            Add("t4.end.1", "jida", "telling", "He slid down the roof into the last stack of tiles. It came down on her, and she went down the chimney like a sack of flour.", "Yeḥudd ɣef ssqef ɣer ukeddus aneggaru. Yeɣli fell-as, teɣli deg ddexxan am tcekkart n uwren.", "Il glissa le long du toit jusque dans la dernière pile de tuiles. Elle lui tomba dessus, et elle descendit par la cheminée comme un sac de farine.", "انزلق على السطح نحو آخر كومة قرميد. فسقطت عليها، فنزلت عبر المدخنة ككيس طحين.");
            Add("t4.end.2", "teryel", "", "My bread! Who took my bread?!", "Aɣrum-iw! Anwa i yeddmen aɣrum-iw?!", "Mon pain ! Qui a pris mon pain ?!", "خبزي! من أخذ خبزي؟!");
            Add("t4.end.3", "jida", "teasing", "It was never her bread. He carried it home across the roofs, still warm.", "Ur yelli ara d aɣrum-is. Yerra-t s axxam ɣef ssqef, mazal yeḥma.", "Ce n'était pas son pain. Il le rapporta à la maison par les toits, encore chaud.", "لم يكن خبزها أبدا. حمله إلى البيت عبر السطوح، وما زال دافئا.");
            Add("t4.end.4", "boy", "", "Can we eat it now?", "Nezmer ad t-nečč tura?", "On peut le manger maintenant ?", "هل نستطيع أكله الآن؟");
            Add("t4.end.5", "jida", "teasing", "After the tale. Always after the tale.", "Deffir tmacahut. Yal tikkelt deffir tmacahut.", "Après le conte. Toujours après le conte.", "بعد الحكاية. دائما بعد الحكاية.");
            Add("tip.slide", "", "", "Old tiles slide. Land on a roof to slide down it, fast. Tap to hop off.", "Iqermuden iqdimen ttḥuddun. Ɣli ɣef ssqef ad tḥuddeḍ. Sṭebṭeb ad tneggzeḍ.", "Les vieilles tuiles glissent. Pose-toi sur un toit pour le descendre vite. Tape pour sauter.", "القرميد القديم ينزلق. اهبط على سطح لتنزلق عليه بسرعة. انقر لتقفز.");
            Add("tip.knock", "", "", "Loose tiles. Hit the stack hard and it goes over the edge, onto whatever is below.", "Iqermuden ttḥerriken. Wwet akeddus s ǧǧehd ad yeɣli seg rrif ɣef wayen yellan ddaw-s.", "Des tuiles branlantes. Frappe la pile fort et elle bascule, sur ce qui se trouve en dessous.", "قرميد متخلخل. اضرب الكومة بقوّة فتسقط من الحافة على ما تحتها.");
            Add("tip.raven", "", "", "Her ravens. Hit them fast, or they peck.", "Ijeɣdan-is. Wwet-iten s zzerb, neɣ ad k-qqsen.", "Ses corbeaux. Frappe-les vite, ou ils piquent.", "غربانها. اضربها بسرعة، وإلا نقرتك.");
            Add("r.slide", "boy", "", "Wheee!", "Iwwah!", "Youpi !", "ووو!");
            Add("r.knock", "girl", "", "It fell!", "Yeɣli!", "Elle est tombée !", "سقطت!");
            Add("tale.4", "", "", "The rooftops of Lqelɛa", "Ssqef n Lqelɛa", "Les toits de Lqelɛa", "سطوح القلعة");
            Add("stage.13", "", "", "The tiles", "Iqermuden", "Les tuiles", "القرميد");
            Add("stage.14", "", "", "The ravens", "Ijeɣdan", "Les corbeaux", "الغربان");
            Add("stage.15", "", "", "The roof", "Ssqef", "Le toit", "السطح");
            Add("stage.16", "", "", "Teryel on the roof", "Teryel ɣef ssqef", "Teryel sur le toit", "تريال على السطح");
            Add("t5.intro.1", "jida", "telling", "Before I was a grandmother, I was a bride. On my wedding day my mother gave me a silver tabzimt, round as the moon, with red coral and blue enamel.", "Uqbel ad iliɣ d jida, lliɣ d tislit. Ass n tmeɣra-w, yemma tuɣ-iyi-d tabzimt n lfeṭṭa, tezzi am waggur, s lmerǧan azeggaɣ d uzerwal.", "Avant d'être grand-mère, j'ai été mariée. Le jour de mes noces, ma mère m'a offert une tabzimt d'argent, ronde comme la lune, avec du corail rouge et de l'émail bleu.", "قبل أن أصير جدّة، كنت عروسا. يوم عرسي، أهدتني أمي تابزيمت من فضة، مستديرة كالقمر، بمرجان أحمر ومينا زرقاء.");
            Add("t5.intro.2", "girl", "", "The one in your chest? I never saw it.", "Tin yellan deg usenduq-im? Werǧin ẓriɣ-tt.", "Celle de ton coffre ? Je ne l'ai jamais vue.", "التي في صندوقك؟ لم أرها أبدا.");
            Add("t5.intro.3", "jida", "hushed", "Because Teryel took it. She loves everything that shines. She hid it in the old olive press, deep in the oil.", "Acku Teryel tewwi-tt. Tḥemmel kra yettceɛcuɛen. Teffer-itt deg tmɛeṣert taqdimt, deg zzit.", "Parce que Teryel l'a prise. Elle aime tout ce qui brille. Elle l'a cachée dans le vieux pressoir à olives, au fond de l'huile.", "لأن تريال أخذتها. إنها تحب كل ما يلمع. خبّأتها في معصرة الزيتون القديمة، في أعماق الزيت.");
            Add("t5.intro.4", "jida", "telling", "In winter the press works day and night. The great wheel turns, the floor is slick with oil, and the rats grow fat.", "Di tegrest, tamɛeṣert txeddem iḍ d wass. Tasirt tezzi, akal yeččur d zzit, iɣerdayen ttimɣuren.", "En hiver, le pressoir tourne jour et nuit. La grande roue tourne, le sol est glissant d'huile, et les rats engraissent.", "في الشتاء تعمل المعصرة ليلا ونهارا. تدور العجلة الكبيرة، والأرض زلقة بالزيت، والجرذان تسمن.");
            Add("t5.intro.5", "boy", "", "Fat rats... and Mqidec is small.", "Iɣerdayen imeqranen... u Mqidec meẓẓi.", "Des gros rats... et Mqidec est petit.", "جرذان سمينة... ومقيدش صغير.");
            Add("t5.intro.6", "jida", "teasing", "Small, yes. And quick.", "Meẓẓi, ih. Maca ifessus.", "Petit, oui. Et rapide.", "صغير، نعم. لكنه سريع.");
            Add("t5.s1", "jida", "", "Oil on the beams. Land fast and you glide all the way to the end, onto whatever sleeps there.", "Zzit ɣef yigejdan. Ɣli s zzerb ad tḥuddeḍ armi d taggara, ɣef wayen yeṭṭsen dinna.", "De l'huile sur les poutres. Pose-toi vite et tu glisses jusqu'au bout, sur ce qui dort là-bas.", "زيت على العوارض. اهبط بسرعة فتنزلق حتى النهاية، نحو ما ينام هناك.");
            Add("t5.s1.child", "girl", "", "Like on ice!", "Am ugris!", "Comme sur la glace !", "مثل الجليد!");
            Add("t5.s2", "jida", "", "The great wheel never stops. Stand on a plank and it lifts you, slowly. Jump when you are high enough.", "Tasirt ur tettḥebbis ara. Bedd ɣef tfelwit ad k-terfed s leɛqel. Neggez mi ara tiliḍ d afella.", "La grande roue ne s'arrête jamais. Pose-toi sur une planche et elle te monte, doucement. Saute quand tu es assez haut.", "العجلة الكبيرة لا تتوقف. قف على لوح فيرفعك ببطء. اقفز حين تبلغ العلوّ.");
            Add("t5.s2.child", "boy", "", "Round and round!", "Tezzi, tezzi!", "Elle tourne, elle tourne !", "تدور وتدور!");
            Add("t5.s3", "jida", "", "Up with the wheel, then down onto the oil. The rats never see him coming.", "Ali deg tsirt, syin ader ɣer zzit. Iɣerdayen ur t-ttwalin ara yettas.", "Monte avec la roue, puis redescends sur l'huile. Les rats ne le voient pas venir.", "اصعد بالعجلة، ثم انزل على الزيت. الجرذان لا تراه قادما.");
            Add("t5.s3.child", "girl", "", "The rats are too slow!", "Iɣerdayen ttɛeṭṭilen!", "Les rats sont trop lents !", "الجرذان بطيئة!");
            Add("t5.s4", "jida", "hushed", "And under the great beam of the press, Teryel paced up and down, my tabzimt pinned on her shoulder.", "Ddaw usalas ameqran n tmɛeṣert, Teryel tteddu u tettuɣal, tabzimt-iw ɣef tayett-is.", "Et sous la grande poutre du pressoir, Teryel faisait les cent pas, ma tabzimt épinglée à l'épaule.", "وتحت العارضة الكبرى للمعصرة، كانت تريال تروح وتجيء، وتابزيمتي على كتفها.");
            Add("t5.s4.child", "boy", "", "Push the beam! On her head!", "Ḍeqqer asalas! Ɣef uqerru-s!", "Pousse la poutre ! Sur sa tête !", "ادفع العارضة! على رأسها!");
            Add("t5.end.1", "jida", "telling", "He ran along the oily beam, faster and faster, and struck the great beam of the press. It rolled off its ledge and came down on Teryel's back.", "Yazzel ɣef yigejdi n zzit, s zzerb, yewwet asalas ameqran. Yeɣli seg wemkan-is, yers ɣef tuyat n Teryel.", "Il courut sur la poutre huilée, de plus en plus vite, et heurta la grande poutre du pressoir. Elle roula de son appui et tomba sur le dos de Teryel.", "ركض على العارضة المزيّتة، أسرع فأسرع، وضرب عارضة المعصرة الكبرى. تدحرجت عن مكانها وسقطت على ظهر تريال.");
            Add("t5.end.2", "teryel", "", "Oil in my hair! Rats in my bed! Where is my shiny thing?!", "Zzit deg ucebbub-iw! Iɣerdayen deg wusu-w! Anda-t wayen-iw yettceɛcuɛen?!", "De l'huile dans mes cheveux ! Des rats dans mon lit ! Où est ma chose qui brille ?!", "زيت في شعري! جرذان في فراشي! أين شيئي اللامع؟!");
            Add("t5.end.3", "jida", "teasing", "It was never hers. Mqidec carried it home in his mouth, gently, the way a cat carries her kitten.", "Ur telli ara d ayla-s. Mqidec yerra-tt-id s axxam deg yimi-s, s leɛqel, am tmacict mi ara terfed mmi-s.", "Elle n'a jamais été à elle. Mqidec la rapporta à la maison dans sa bouche, doucement, comme une chatte porte son petit.", "لم تكن لها أبدا. أعادها مقيدش إلى البيت في فمه، بلطف، كما تحمل القطة صغيرها.");
            Add("t5.end.4", "girl", "", "Can I wear it? Just once?", "Zemreɣ ad tt-lseɣ? Yiwet n tikkelt kan?", "Je peux la porter ? Juste une fois ?", "هل أستطيع أن ألبسها؟ مرة واحدة فقط؟");
            Add("t5.end.5", "jida", "telling", "On your wedding day. And not one day sooner.", "Ass n tmeɣra-m. Ur yezwir ara yiwen wass.", "Le jour de tes noces. Et pas un jour avant.", "يوم عرسك. ولا يوما قبله.");
            Add("tip.oil", "", "", "Spilt oil. Land fast and you glide on, into whatever sits at the end. Land gently and you stop.", "Zzit yeɣli. Ɣli s zzerb ad tḥuddeḍ armi d ayen yellan di taggara. Ɣli s leɛqel ad tbeddeḍ.", "De l'huile renversée. Pose-toi vite et tu glisses jusqu'à ce qui se trouve au bout. Pose-toi doucement et tu t'arrêtes.", "زيت مسكوب. اهبط بسرعة فتنزلق نحو ما في آخره. اهبط بلطف فتتوقف.");
            Add("tip.wheel", "", "", "The press wheel never stops. Rest on a plank and it carries you round. Launch from the top.", "Tasirt n tmɛeṣert ur tettḥebbis ara. Bedd ɣef tfelwit ad k-tezzi yid-s. Neggez seg ufella.", "La roue du pressoir ne s'arrête jamais. Pose-toi sur une planche et elle t'emporte. Élance-toi d'en haut.", "عجلة المعصرة لا تتوقف. قف على لوح فيحملك معه. انطلق من الأعلى.");
            Add("tip.rat", "", "", "Her rats run along the beams. Hit them fast, or they bite.", "Iɣerdayen-is ttazzalen ɣef yigejdan. Wwet-iten s zzerb, neɣ ad k-qqesen.", "Ses rats courent sur les poutres. Frappe-les vite, ou ils mordent.", "جرذانها تركض على العوارض. اضربها بسرعة، وإلا عضّتك.");
            Add("r.oil", "boy", "", "Slippery!", "Yeceḍḍeḍ!", "Ça glisse !", "زلق!");
            Add("r.wheel", "girl", "", "Up he goes!", "Atan yuli!", "Il monte !", "ها هو يصعد!");
            Add("tale.5", "", "", "The olive press", "Tamɛeṣert", "Le pressoir à olives", "معصرة الزيتون");
            Add("stage.17", "", "", "The oil", "Zzit", "L'huile", "الزيت");
            Add("stage.18", "", "", "The wheel", "Tasirt", "La roue", "العجلة");
            Add("stage.19", "", "", "The olives", "Azemmur", "Les olives", "الزيتون");
            Add("stage.20", "", "", "Teryel in the press", "Teryel deg tmɛeṣert", "Teryel au pressoir", "تريال في المعصرة");
            Add("t6.intro.1", "jida", "telling", "One summer the rain forgot us. The spring under the fig tree gave one drop, then none.", "Yiwen unebdu, ageffur yettu-yaɣ. Tala ddaw tneqlet tefka-d yiwet n tqit, syin ulac.", "Un été, la pluie nous oublia. La source sous le figuier donna une goutte, puis plus rien.", "في صيف ما، نسينا المطر. أعطى النبع تحت شجرة التين قطرة واحدة، ثم لا شيء.");
            Add("t6.intro.2", "boy", "", "So you called Anzar!", "Ihi tsawlem i Wanzar!", "Alors vous avez appelé Anzar !", "فناديتم أنزار!");
            Add("t6.intro.3", "jida", "telling", "We dressed the ladle as a bride, Tislit n Wanzar, and carried her from door to door. Every house poured a little water on her.", "Nlures aɣenja am tislit, Tislit n Wanzar, nebbwi-tt seg tewwurt ɣer tayeḍ. Yal axxam yessenɣel fell-as ciṭ n waman.", "Nous avons habillé la louche en mariée, Tislit n Wanzar, et l'avons portée de porte en porte. Chaque maison versait sur elle un peu d'eau.", "ألبسنا المغرفة ثوب عروس، تسليت ن ونزار، وحملناها من باب إلى باب. كل بيت كان يسكب عليها قليلا من الماء.");
            Add("t6.intro.4", "jida", "hushed", "But the night before, Teryel stole her. \"A bride with no rain,\" she laughed, \"is a bride for me.\" She hid her in the old cistern above the spring.", "Maca deg yiḍ uqbel, Teryel tukker-itt. \"Tislit war ageffur,\" i tenna s taḍsa, \"d tislit-iw.\" Teffer-itt deg lǧeb aqdim nnig tala.", "Mais la nuit d'avant, Teryel l'a volée. « Une mariée sans pluie, ricana-t-elle, c'est une mariée pour moi. » Elle l'a cachée dans la vieille citerne au-dessus de la source.", "لكن في الليلة السابقة، سرقتها تريال. «عروس بلا مطر»، قالت ضاحكة، «هي عروس لي». خبّأتها في الصهريج القديم فوق النبع.");
            Add("t6.intro.5", "girl", "", "And the frogs? There are always frogs at a spring.", "Imqerqar? Llan yal tikkelt imqerqar di tala.", "Et les grenouilles ? Il y a toujours des grenouilles à la source.", "والضفادع؟ هناك دائما ضفادع عند النبع.");
            Add("t6.intro.6", "jida", "teasing", "Hers, every one. Thirsty, and in a very bad mood.", "D ayla-s, akk. Ffuden, u zeɛfen aṭas.", "Les siennes, toutes. Assoiffées, et de très mauvaise humeur.", "ضفادعها، كلها. عطشى، ومزاجها سيّئ جدا.");
            Add("t6.s1", "jida", "", "One last pool was left under the fig tree. Fall in and it holds you up, like a hand. Jump again from the surface.", "Yeqqim-d yiwen n umdun ddaw tneqlet. Ɣli deg-s ad k-yeṭṭef am ufus. Neggez seg ufella n waman.", "Il restait une dernière mare sous le figuier. Tombe dedans, elle te porte comme une main. Ressaute depuis la surface.", "بقيت بركة أخيرة تحت شجرة التين. اسقط فيها فتحملك كاليد. اقفز من جديد من سطح الماء.");
            Add("t6.s1.child", "girl", "", "He can swim?", "Yessen ad iɛum?", "Il sait nager ?", "هل يعرف السباحة؟");
            Add("t6.s2", "jida", "", "Two buckets on one rope over the well. When one goes down, the other comes up. Drop a stone in one, and see who flies.", "Sin isiṭlen ɣef yiwen wemrar nnig lbir. Mi ara yader yiwen, wayeḍ ad yali. Ḍeqqer azru deg yiwen, ad twaliḍ anwa ara yafgen.", "Deux seaux sur une seule corde au-dessus du puits. Quand l'un descend, l'autre monte. Laisse tomber une pierre dans l'un, et regarde qui s'envole.", "دلوان على حبل واحد فوق البئر. حين ينزل أحدهما يصعد الآخر. ألق حجرا في أحدهما وانظر من يطير.");
            Add("t6.s2.child", "boy", "", "I want a go!", "Bɣiɣ ad ɛerḍeɣ!", "Je veux essayer !", "أريد أن أجرّب!");
            Add("t6.s3", "jida", "", "The well was deep and dark, with a little water still at the bottom. Down with one bucket, up with the other.", "Lbir d alqayan u yeḍles, yella ciṭ n waman deg wadda-s. Ader s yiwen usiṭel, ali s wayeḍ.", "Le puits était profond et noir, avec encore un peu d'eau au fond. Descends avec un seau, remonte avec l'autre.", "كانت البئر عميقة ومظلمة، وفي قاعها قليل من الماء. انزل بدلو، واصعد بالآخر.");
            Add("t6.s3.child", "girl", "", "I don't like wells.", "Ur ḥemmleɣ ara lbir.", "Je n'aime pas les puits.", "لا أحب الآبار.");
            Add("t6.s4", "jida", "hushed", "And in the dry bed below the cistern sat Teryel, the ladle bride in her hands, and all the water of the village behind one cracked wall.", "Deg wasif aqqur ddaw lǧeb teqqim Teryel, Tislit n Wanzar deg yifassen-is, u akk aman n taddart deffir yiwen uɣrab yeqqersen.", "Et dans le lit asséché sous la citerne était assise Teryel, la mariée d'Anzar entre les mains, et toute l'eau du village derrière un seul mur fendu.", "وفي المجرى الجاف تحت الصهريج جلست تريال، وعروس أنزار بين يديها، وكل ماء القرية خلف جدار واحد متصدّع.");
            Add("t6.s4.child", "boy", "", "Break the wall! Let the water out!", "Ṛẓ aɣrab! Ssuffeɣ aman!", "Casse le mur ! Fais sortir l'eau !", "اكسر الجدار! أطلق الماء!");
            Add("t6.end.1", "jida", "telling", "He struck the cracked wall with all his speed. The stones gave, the water came down the ravine like a white horse, and Teryel went with it.", "Yewwet aɣrab s akk zzerb-is. Izra ɣlin, aman ṛuḥen deg uɣzer am uyis amellal, u Teryel tedda yid-sen.", "Il frappa le mur fendu de toute sa vitesse. Les pierres cédèrent, l'eau dévala le ravin comme un cheval blanc, et Teryel partit avec elle.", "ضرب الجدار المتصدّع بكل سرعته. انهارت الحجارة، ونزل الماء في الوادي كحصان أبيض، وذهبت تريال معه.");
            Add("t6.end.2", "teryel", "", "Water! Water in my ears! Who taught that little thing to break walls?!", "Aman! Aman deg yimeẓẓuɣen-iw! Anwa i yesselmden ayen-nni ameẓẓyan ad yerreẓ iɣraben?!", "De l'eau ! De l'eau dans mes oreilles ! Qui a appris à ce petit machin à casser les murs ?!", "ماء! ماء في أذنيّ! من علّم هذا الصغير كسر الجدران؟!");
            Add("t6.end.3", "jida", "telling", "Mqidec carried the ladle bride back to the village on his back. That same night the clouds came down from the Bibans.", "Mqidec yerra-d Tislit n Wanzar ɣer taddart ɣef tuyat-is. Deg yiḍ-nni kan, isigna d-ḥedren seg Lbiban.", "Mqidec rapporta la mariée d'Anzar au village sur son dos. La nuit même, les nuages descendirent des Bibans.", "حمل مقيدش عروس أنزار إلى القرية على ظهره. وفي الليلة نفسها، نزلت الغيوم من البيبان.");
            Add("t6.end.4", "girl", "", "Listen! It's raining, Jida! It's really raining!", "Sell! Ageffur, a Jida! Ageffur s tidet!", "Écoute ! Il pleut, Jida ! Il pleut pour de vrai !", "اسمعي! إنها تمطر يا جدّة! تمطر حقا!");
            Add("t6.end.5", "jida", "teasing", "Then sing with me, the way we sang that summer. Anzar, Anzar, O God, water it down to the roots!", "Ihi cnut yid-i, akken i ncennu anebdu-nni. Anzar, Anzar, a Rebbi sew-it ar iẓuran!", "Alors chantez avec moi, comme nous chantions cet été-là. Anzar, Anzar, ô Dieu, abreuve-la jusqu'aux racines !", "إذن غنّوا معي، كما غنّينا ذلك الصيف. أنزار، أنزار، يا ربّ اسقها حتى الجذور!");
            Add("tip.water", "", "", "Water. Fall in and it holds you up. Launch again from the surface once you are still.", "Aman. Ɣli deg-sen ad k-ṭṭfen. Neggez seg ufella mi ara tersiḍ.", "De l'eau. Tombe dedans, elle te porte. Relance-toi depuis la surface une fois immobile.", "ماء. اسقط فيه فيحملك. انطلق من السطح من جديد حين تهدأ.");
            Add("tip.bucket", "", "", "Two buckets on one rope. Your weight takes yours down and the other up. A stone dropped in one throws whatever stands in the other.", "Sin isiṭlen ɣef yiwen wemrar. Taẓayt-ik ad tesder asiṭel-ik, wayeḍ ad yali. Azru yeɣlin deg yiwen ad yeḍeqqer ayen yellan deg wayeḍ.", "Deux seaux sur une seule corde. Ton poids fait descendre le tien et monter l'autre. Une pierre tombée dans l'un projette ce qui se tient dans l'autre.", "دلوان على حبل واحد. وزنك ينزل دلوك ويرفع الآخر. حجر يسقط في أحدهما يقذف ما يقف في الآخر.");
            Add("tip.frog", "", "", "Her frogs leap when you come near. Hit them fast, or they bite.", "Imqerqar-is ttneggizen mi ara d-tqerbeḍ. Wwet-iten s zzerb, neɣ ad k-qqesen.", "Ses grenouilles bondissent quand tu approches. Frappe-les vite, ou elles mordent.", "ضفادعها تقفز حين تقترب. اضربها بسرعة، وإلا عضّتك.");
            Add("tip.cistern", "", "", "A cracked wall holding back water. A hard hit or a dash breaks it, and the water goes where it likes.", "Aɣrab yeqqersen yeṭṭfen aman. Tiyita s zzerb neɣ tazzla ad t-tṛeẓ, aman ad ṛuḥen anda bɣan.", "Un mur fendu qui retient l'eau. Un choc fort ou une ruée le brise, et l'eau va où elle veut.", "جدار متصدّع يحبس الماء. ضربة قوية أو اندفاعة تكسره، فيذهب الماء حيث يشاء.");
            Add("tip.tied", "", "", "A stone tied to the well rope. Rest a moment in a bucket and the rope slips: the stone drops into the other bucket.", "Azru yeqqnen ɣer wemrar n lbir. Ẓẓeg ciṭ deg usiṭel, amrar ad yerxu: azru ad yeɣli deg usiṭel wayeḍ.", "Une pierre attachée à la corde du puits. Reste un instant dans un seau et la corde glisse : la pierre tombe dans l'autre seau.", "حجر مربوط بحبل البئر. ابق لحظة في دلو فينزلق الحبل: يسقط الحجر في الدلو الآخر.");
            Add("r.splash", "girl", "", "Splash!", "Bluf!", "Plouf !", "طرطش!");
            Add("r.jerk", "boy", "", "He flew!", "Yafeg!", "Il s'envole !", "طار!");
            Add("r.flood", "boy", "", "The water! The water!", "Aman! Aman!", "L'eau ! L'eau !", "الماء! الماء!");
            Add("tale.6", "", "", "The bride of Anzar", "Tislit n Wanzar", "La mariée d'Anzar", "عروس أنزار");
            Add("stage.21", "", "", "The spring", "Tala", "La source", "النبع");
            Add("stage.22", "", "", "The bucket", "Asiṭel", "Le seau", "الدلو");
            Add("stage.23", "", "", "The well", "Lbir", "Le puits", "البئر");
            Add("stage.24", "", "", "Teryel at the spring", "Teryel deg tala", "Teryel à la source", "تريال عند النبع");
            Add("t7.intro.1", "jida", "telling", "Do you know why Yennayer has borrowed days? Once an old woman laughed at January. \"Your cold is nothing,\" she said, and drove her goats up the mountain.", "Tessnem acuɣer Yennayer yesɛa ussan yettwareḍlen? Yiwet n tmeɣart teḍsa ɣef Yennayer. \"Asemmiḍ-ik d ulac,\" i as-tenna, tessali iɣeṭṭen-is ɣer wedrar.", "Vous savez pourquoi Yennayer a des jours empruntés ? Une vieille femme s'est un jour moquée de janvier. « Ton froid n'est rien », lui dit-elle, et elle mena ses chèvres sur la montagne.", "أتعرفون لماذا ليناير أيام مستعارة؟ ذات مرة سخرت عجوز من يناير. «بردك لا شيء»، قالت له، وساقت ماعزها إلى الجبل.");
            Add("t7.intro.2", "boy", "", "And January got angry!", "U Yennayer yezɛef!", "Et janvier s'est fâché !", "فغضب يناير!");
            Add("t7.intro.3", "jida", "hushed", "He borrowed days from February, and on the last of them he froze her and her goats into rock. They are still up there on the Djurdjura.", "Yerḍel ussan seg Furar, deg wass aneggaru yesqer-itt nettat d iɣeṭṭen-is, uɣalen d iẓra. Mazal-iten dinna deg Ǧerǧer.", "Il emprunta des jours à février, et le dernier d'entre eux il la changea en rocher, elle et ses chèvres. Elles sont toujours là-haut, sur le Djurdjura.", "استعار أياما من فبراير، وفي آخرها جمّدها هي وماعزها فصارت صخورا. ما زالت هناك فوق جرجرة.");
            Add("t7.intro.4", "jida", "telling", "Teryel was that old woman's friend. When the cold came, she ran off with the old woman's spindle, goat hair still wound on it, and dropped it on the frozen pasture.", "Teryel tella d tamddakelt n tmeɣart-nni. Mi d-yusa usemmiḍ, terwel s yizdi n tmeɣart, mazal ccɛer n tɣaṭ fell-as, teǧǧa-t deg wegni yeqqren.", "Teryel était l'amie de cette vieille femme. Quand le froid arriva, elle s'enfuit avec le fuseau de la vieille, encore garni de poil de chèvre, et le laissa tomber sur l'alpage gelé.", "كانت تريال صديقة تلك العجوز. لما جاء البرد، هربت بمغزل العجوز، وما زال عليه شعر الماعز، وأسقطته في المرعى المتجمّد.");
            Add("t7.intro.5", "girl", "", "Why does Mqidec want an old spindle?", "Acuɣer i yebɣa Mqidec izdi aqdim?", "Pourquoi Mqidec veut-il un vieux fuseau ?", "لماذا يريد مقيدش مغزلا قديما؟");
            Add("t7.intro.6", "jida", "teasing", "Because my grandmother spun with it, and her blanket is the one on your knees.", "Acku jida-w tellem yis-s, abeṭṭan-is d win yellan ɣef tgecrar-im.", "Parce que ma grand-mère filait avec, et sa couverture est celle qui est sur tes genoux.", "لأن جدّتي كانت تغزل به، وغطاؤها هو الذي على ركبتيك.");
            Add("t7.s1", "jida", "", "The pond up there breathes with the wind. When it blows, the water turns to ice you can stand on. When it stops, the ice is water again.", "Tamda n dinna tettneffis d waḍu. Mi ara yeṣṣuḍ, aman ad uɣalen d agris ara k-yerfden. Mi ara yeḥbes, agris ad yuɣal d aman.", "La mare là-haut respire avec le vent. Quand il souffle, l'eau devient une glace qui te porte. Quand il s'arrête, la glace redevient eau.", "البركة هناك تتنفس مع الريح. حين تهب، يصير الماء جليدا يحملك. حين تسكن، يعود الجليد ماء.");
            Add("t7.s1.child", "girl", "", "Quick, before it melts!", "Ɣiwel, uqbel ad yefsi!", "Vite, avant que ça fonde !", "بسرعة، قبل أن يذوب!");
            Add("t7.s2", "jida", "", "The goats charge when they see you standing still. But the snow is deep, and a goat in a drift is a goat stuck.", "Iɣeṭṭen ttazzalen-d fell-ak mi ara k-walin tbeddeḍ. Maca adfel d alqayan, aɣeṭṭ deg wedfel yeqqim yeṭṭef.", "Les chèvres chargent quand elles te voient immobile. Mais la neige est profonde, et une chèvre dans une congère est une chèvre coincée.", "الماعز تنطح حين تراك واقفا. لكن الثلج عميق، والعنزة في كومة الثلج عنزة عالقة.");
            Add("t7.s2.child", "boy", "", "Make it run into the snow!", "Ǧǧ-it ad yazzel ɣer wedfel!", "Fais-la foncer dans la neige !", "اجعلها تركض نحو الثلج!");
            Add("t7.s3", "jida", "", "Ice, snow and goats, all at once. Mqidec listened to the wind and counted, like this: one, two, now.", "Agris, adfel d iɣeṭṭen, akk ɣef tikkelt. Mqidec yesla i waḍu, yeḥseb akka: yiwen, sin, tura.", "La glace, la neige et les chèvres, tout à la fois. Mqidec écoutait le vent et comptait, comme ça : un, deux, maintenant.", "الجليد والثلج والماعز، كلها معا. أصغى مقيدش إلى الريح وعدّ هكذا: واحد، اثنان، الآن.");
            Add("t7.s3.child", "girl", "", "One, two, now!", "Yiwen, sin, tura!", "Un, deux, maintenant !", "واحد، اثنان، الآن!");
            Add("t7.s4", "jida", "hushed", "In the hollow under the snow cornice, Teryel sat spinning with the old woman's spindle, singing to the stone goats.", "Deg yiɣzer ddaw uqerru n wedfel, Teryel teqqim tellem s yizdi n tmeɣart, tcennu i yiɣeṭṭen n weẓru.", "Dans le creux sous la corniche de neige, Teryel filait avec le fuseau de la vieille et chantait pour les chèvres de pierre.", "في التجويف تحت حافة الثلج، كانت تريال تغزل بمغزل العجوز وتغنّي لماعز الحجر.");
            Add("t7.s4.child", "boy", "", "Drop the snow on her!", "Ssɣli adfel fell-as!", "Fais tomber la neige sur elle !", "أسقط الثلج عليها!");
            Add("t7.end.1", "jida", "telling", "He struck the cornice with all his speed. The whole lip of snow broke off, came down the slope and filled the hollow to the brim, with Teryel in it.", "Yewwet aqerru n wedfel s akk zzerb-is. Yeɣli akk, yers-d seg uḍrar, yeččur yiɣzer armi d imi-s, Teryel daxel.", "Il frappa la corniche de toute sa vitesse. Toute la lèvre de neige se détacha, dévala la pente et remplit le creux jusqu'au bord, avec Teryel dedans.", "ضرب حافة الثلج بكل سرعته. انفصلت كلها ونزلت المنحدر وملأت التجويف حتى حافته، وتريال فيه.");
            Add("t7.end.2", "teryel", "", "Cold! Cold! Who has my nose? I can't feel my nose!", "Asemmiḍ! Asemmiḍ! Anwa i yeṭṭfen tinzert-iw? Ur ḥussaɣ ara s tinzert-iw!", "Froid ! Froid ! Qui a mon nez ? Je ne sens plus mon nez !", "برد! برد! من أخذ أنفي؟ لا أشعر بأنفي!");
            Add("t7.end.3", "jida", "telling", "Mqidec walked home over the snowbank with the spindle on his shoulder. The next morning was the first day of February, and the snow stopped.", "Mqidec yuɣal s axxam ɣef wedfel, izdi ɣef tayett-is. Azekka-nni d ass amezwaru n Furar, adfel yeḥbes.", "Mqidec rentra à la maison par-dessus le banc de neige, le fuseau sur l'épaule. Le lendemain était le premier jour de février, et la neige s'arrêta.", "عاد مقيدش إلى البيت فوق ركام الثلج، والمغزل على كتفه. وكان الصباح التالي أول يوم من فبراير، فتوقف الثلج.");
            Add("t7.end.4", "girl", "", "And the old woman? Is she still a rock?", "Tamɣart-nni? Mazal-itt d aẓru?", "Et la vieille femme ? Elle est toujours un rocher ?", "والعجوز؟ هل ما زالت صخرة؟");
            Add("t7.end.5", "jida", "teasing", "Look at the Djurdjura in the morning. She is the one with her goats around her. So never laugh at January.", "Muqel Ǧerǧer taṣebḥit. D nettat i yellan s iɣeṭṭen-is i tt-yezzin. Ihi ur ttaḍsat ara ɣef Yennayer.", "Regarde le Djurdjura au matin. C'est elle, avec ses chèvres autour. Alors ne vous moquez jamais de janvier.", "انظري إلى جرجرة في الصباح. هي تلك التي حولها ماعزها. فلا تسخروا أبدا من يناير.");
            Add("tip.ice", "", "", "The pond freezes on the wind's beat. Stand on the ice while it lasts: it is slippery, and when it thaws you are in the water.", "Tamda tesqar s waḍu. Bedd ɣef ugris ma yella: yeceḍḍeḍ, mi ara yefsi atan deg waman.", "La mare gèle au rythme du vent. Tiens-toi sur la glace tant qu'elle dure : elle glisse, et quand elle fond tu es dans l'eau.", "تتجمّد البركة مع هبوب الريح. قف على الجليد ما دام: إنه زلق، وحين يذوب تصير في الماء.");
            Add("tip.drift", "", "", "A snowdrift. Land in it and you stop dead. A charging goat that runs into it gets stuck.", "Adfel yettwaǧmeɛ. Ɣli deg-s ad tbeddeḍ imir. Aɣeṭṭ ara d-yazzlen ɣur-s ad yeqqim yeṭṭef.", "Une congère. Pose-toi dedans et tu t'arrêtes net. Une chèvre qui fonce dedans reste coincée.", "كومة ثلج. اهبط فيها فتتوقف فورا. والعنزة التي تندفع نحوها تعلق.");
            Add("tip.goat", "", "", "Her goats charge when you stand still on their level. A goat stuck in snow breaks at a touch.", "Iɣeṭṭen-is ttazzalen-d fell-ak mi ara tbeddeḍ ɣef uswir-nsen. Aɣeṭṭ yeṭṭfen deg wedfel ad yerreẓ s tiyita kan.", "Ses chèvres chargent quand tu restes immobile à leur hauteur. Une chèvre coincée dans la neige se brise au moindre contact.", "ماعزها تنطح حين تقف ساكنا في مستواها. والعنزة العالقة في الثلج تنكسر بلمسة.");
            Add("tip.cornice", "", "", "A lip of snow hanging over the hollow. A hard hit or a dash breaks it off, and the snow fills everything below.", "Aqerru n wedfel yettwaɛlaq nnig yiɣzer. Tiyita s zzerb neɣ tazzla ad t-tesɣli, adfel ad yeččar ayen yellan ddaw-s.", "Une corniche de neige au-dessus du creux. Un choc fort ou une ruée la détache, et la neige remplit tout en dessous.", "حافة ثلج معلّقة فوق التجويف. ضربة قوية أو اندفاعة تسقطها، فيملأ الثلج كل ما تحتها.");
            Add("r.freeze", "girl", "", "It's freezing!", "Yesqer!", "Ça gèle !", "إنه يتجمّد!");
            Add("r.thaw", "boy", "", "It's melting!", "Yefsi!", "Ça fond !", "إنه يذوب!");
            Add("r.stuck", "boy", "", "Stuck in the snow!", "Yeṭṭef deg wedfel!", "Coincée dans la neige !", "عالقة في الثلج!");
            Add("r.avalanche", "boy", "", "The snow! All of it!", "Adfel! Akk!", "La neige ! Toute la neige !", "الثلج! كله!");
            Add("tale.7", "", "", "The old woman's borrowed days", "Ussan n tmeɣart", "Les jours empruntés de la vieille", "أيام العجوز المستعارة");
            Add("stage.25", "", "", "The ice", "Agris", "La glace", "الجليد");
            Add("stage.26", "", "", "The snow", "Adfel", "La neige", "الثلج");
            Add("stage.27", "", "", "The goats", "Iɣeṭṭen", "Les chèvres", "الماعز");
            Add("stage.28", "", "", "Teryel in the snow", "Teryel deg wedfel", "Teryel dans la neige", "تريال في الثلج");
        }
    }
}
